SELECT settlement_date, revenue_amount, paid_amount, refund_amount, net_amount, order_count, customer_count
FROM agent_v3_daily_settlement_view WHERE agent_v3_daily_settlement_view.store_id = ANY(:allowedStoreIds) AND agent_v3_daily_settlement_view.settlement_date >= :startAt AND agent_v3_daily_settlement_view.settlement_date < :endAt ORDER BY settlement_date DESC
LIMIT 100;

SELECT COALESCE(SUM(o.paid_amount), 0) AS cash_income
FROM agent_v3_order_summary_view AS o
WHERE o.store_id = ANY(:allowedStoreIds) AND o.order_created_at >= :startAt AND o.order_created_at < :endAt AND (o.pay_method = '***') LIMIT 1;

SELECT product_name, sku, unit, current_stock, safety_stock, status, nearest_expiry_date
FROM agent_v3_product_inventory_view
WHERE agent_v3_product_inventory_view.store_id = ANY(:allowedStoreIds) AND (product_name = '***') LIMIT 100;

SELECT product_name, sku, unit, current_stock, safety_stock, status, nearest_expiry_date
FROM agent_v3_product_inventory_view
WHERE agent_v3_product_inventory_view.store_id = ANY(:allowedStoreIds) AND (product_name = '***') LIMIT 100;

SELECT customer_name_masked, member_level
FROM ask_data_customer_profile_summary_view
WHERE ask_data_customer_profile_summary_view.store_id = ANY(:allowedStoreIds) AND (customer_name_masked = '***') LIMIT 100;

SELECT customer_id, customer_name_masked, total_paid_amount
FROM ask_data_customer_profile_summary_view
WHERE ask_data_customer_profile_summary_view.store_id = ANY(:allowedStoreIds) AND (customer_name_masked = '***') LIMIT 100;

SELECT customer_name_masked, member_level
FROM ask_data_customer_profile_summary_view
WHERE ask_data_customer_profile_summary_view.store_id = ANY(:allowedStoreIds) AND (customer_name_masked = '***') LIMIT 100;

SELECT COUNT(customer_id) AS gold_member_count
FROM ask_data_customer_lifecycle_view
WHERE ask_data_customer_lifecycle_view.store_id = ANY(:allowedStoreIds) AND (ltv_tier = '***') LIMIT 100;

SELECT customer_name_masked, total_paid_amount
FROM ask_data_customer_profile_summary_view
WHERE ask_data_customer_profile_summary_view.store_id = ANY(:allowedStoreIds) AND (customer_name_masked = '***') LIMIT 100;

SELECT COUNT(staff_id) AS active_beautician_count
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (status = '***') LIMIT 100;

SELECT COUNT(reservation_id) AS arrival_count
FROM agent_v3_reservation_view
WHERE agent_v3_reservation_view.store_id = ANY(:allowedStoreIds) AND agent_v3_reservation_view.date >= :startAt AND agent_v3_reservation_view.date < :endAt AND (status IN ('***', '***')) LIMIT 100;

SELECT COALESCE(SUM(task_count), 0) AS pending_task_count
FROM agent_v3_marketing_automation_view
WHERE agent_v3_marketing_automation_view.store_id = ANY(:allowedStoreIds) AND agent_v3_marketing_automation_view.latest_task_at >= :startAt AND agent_v3_marketing_automation_view.latest_task_at < :endAt AND (status IN ('***', '***')) LIMIT 100;

SELECT ml.snapshot_date, ml.card_liability
FROM ask_data_member_liability_view AS ml WHERE ml.store_id = ANY(:allowedStoreIds) AND ml.snapshot_date >= :startAt AND ml.snapshot_date < :endAt ORDER BY ml.snapshot_date DESC
LIMIT 1;
